CREATE OR REPLACE FUNCTION public.submit_registration_with_dossier(_form_id uuid,_full_name text,_email text,_answers jsonb) RETURNS TABLE(protocol text, registration_id uuid, document_token text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r record; t text; BEGIN SELECT * INTO r FROM public.submit_registration(_form_id,_full_name,_email,_answers); t:=replace(gen_random_uuid()::text,'-','')||replace(gen_random_uuid()::text,'-',''); INSERT INTO public.registration_dossier_access(registration_id,token_hash) VALUES(r.registration_id,encode(sha256(convert_to(t,'UTF8')),'hex')); RETURN QUERY SELECT r.protocol,r.registration_id,t; END $$;
REVOKE ALL ON FUNCTION public.submit_registration_with_dossier(uuid,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_registration_with_dossier(uuid,text,text,jsonb) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.registration_dossier_source(_token_hash text) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('registration_id',r.id,'protocol',r.protocol,'full_name',r.full_name,'email',r.email,'title',coalesce(r.submission_snapshot->>'title',v.title,f.title),'category',coalesce(r.submission_snapshot->>'category',f.category),'created_at',r.created_at,'updated_at',r.updated_at,'status',r.status,'form_version',r.form_version,'fields',r.fields_snapshot,'answers',r.answers,'consents',r.consent_snapshot,'original',r.submission_snapshot) FROM public.registration_dossier_access a JOIN public.registrations r ON r.id=a.registration_id JOIN public.registration_forms f ON f.id=r.form_id LEFT JOIN public.form_versions v ON v.form_id=r.form_id AND v.version=r.form_version WHERE a.token_hash=_token_hash AND a.expires_at>now() $$;
REVOKE ALL ON FUNCTION public.registration_dossier_source(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.registration_dossier_source(text) TO service_role;